 urls->setPlainText(d.value("sourceUrls").toString());proposals->setPlainText(d.value("proposals").toString());interval->setText(d.value("interval").toString());enabled->setChecked(d.value("enabled").toBool());applySources(d.value("sourceIds").toArray());ack->setChecked(false);baselineSha.clear();readingKey=d.value("readingKey").toString();segment=d.value("segment").toInt();mode=d.value("mode").toInt();if(mode==2){fullText=p.body;exportText=p.exportBody;exportName=p.exportName;showReading();}showMode(mode);
