void IndustryTopicPage::loadTopic(){
 if(topics->currentIndex()<0)return;auto next=topics->currentData().toString();if(next==editorTopic)return;
 try{QJsonObject value;if(topicDrafts.contains(next))value=topicDrafts.value(next);else{QJsonObject task{{"enabled",false},{"intervalMinutes",1440},{"sourceIds",QJsonArray{}},{"sourceUrls",QJsonArray{}},{"proposals",QJsonArray{}}};for(auto v:Store(directory+"/state.json").snapshot().value("tasks").toArray())if(v.toObject().value("topicId")==next)task=v.toObject();QStringList lines;for(auto v:task.value("sourceUrls").toArray())lines.append(v.toString());value={{"schema","native-industry-update-draft/v1"},{"baseline",baselines->currentData().toString()},{"topic",next},{"sourceIds",task.value("sourceIds")},{"sourceUrls",lines.join('\n')},{"proposals",display(task.value("proposals"))},{"enabled",task.value("enabled")},{"interval",QString::number(task.value("intervalMinutes").toInt())},{"mode",0},{"readingKey","archive"},{"segment",0}};}
 auto p=prepareDraft(value,false,false);stashTopicDraft();applyDraft(p);runtime->cancelManual();
 }catch(...){QSignalBlocker block(topics);topics->setCurrentIndex(topics->findData(editorTopic));throw;}
}
void IndustryTopicPage::reloadHistory(){records->clear();auto list=history(Store(directory+"/state.json").snapshot(),topics->currentData().toString());for(int i=list.size()-1;i>=0;--i){auto r=list[i].toObject();auto item=new QListWidgetItem(r.value("label").toString(),records);item->setData(Qt::UserRole,r.value("key").toString());}}
void IndustryTopicPage::showMode(int value){mode=value;++epoch;toolbar->setVisible(value!=2);readerbar->setVisible(value==2);pages->setCurrentIndex(value);}
void IndustryTopicPage::open(QString key){auto snapshot=Store(directory+"/state.json").snapshot();fullText=reading(snapshot,key);exportText=key=="archive"?snapshot.value("archive").toString():key=="original"?snapshot.value("originalArchive").toString():fullText;exportName=key=="archive"||key=="original"?"产业主题完整档案.json":"产业主题完整阅读.txt";readingKey=key;segment=0;showMode(2);showReading();}
void IndustryTopicPage::showReading(){int count=std::max(1,int((fullText.size()+32767)/32768));segment=std::clamp(segment,0,count-1);int from=segment*32768,to=std::min(int(fullText.size()),from+32768);if(from>0&&fullText[from].isLowSurrogate())--from;if(to<fullText.size()&&fullText[to-1].isHighSurrogate())--to;reader->setPlainText(QString("第 %1 / %2 段 · 全文 %3 字符\n\n").arg(segment+1).arg(count).arg(fullText.size())+fullText.mid(from,to-from));}
